// And groups predicates with the AND operator between them.
func And(predicates ...predicate.EvidenceAnchor) predicate.EvidenceAnchor {
	return predicate.EvidenceAnchor(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.EvidenceAnchor) predicate.EvidenceAnchor {
	return predicate.EvidenceAnchor(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.EvidenceAnchor) predicate.EvidenceAnchor {
	return predicate.EvidenceAnchor(sql.NotPredicates(p))
}
